begin;
create or replace function public.amend_consultation(target_encounter uuid,new_chief_complaint text,new_soap_note text,new_diagnosis text,amendment_reason text) returns void language plpgsql security definer set search_path='' as $$declare fac uuid;org uuid;note uuid;next_version integer;enc_status public.encounter_status;begin select e.facility_id,p.organization_id,e.status into fac,org,enc_status from public.encounters e join public.patients p on p.id=e.patient_id where e.id=target_encounter and e.encounter_type='OPD';if fac is null or not public.has_privilege('clinical.write',fac) then raise exception 'Not authorized';end if;if enc_status='cancelled' then raise exception 'Cancelled encounters are read-only';end if;if nullif(trim(amendment_reason),'') is null then raise exception 'Modification reason is required';end if;select id,current_version into note,next_version from public.clinical_notes where encounter_id=target_encounter and note_type='consultation' order by created_at desc limit 1 for update;next_version:=coalesce(next_version,0)+1;insert into public.clinical_note_versions(note_id,version,content,amendment_reason,author_id) values(note,next_version,jsonb_build_object('chief_complaint',trim(new_chief_complaint),'soap_note',trim(new_soap_note)),trim(amendment_reason),auth.uid());update public.clinical_notes set current_version=next_version where id=note;delete from public.diagnoses where encounter_id=target_encounter and diagnosis_type='working';if nullif(trim(new_diagnosis),'') is not null then insert into public.diagnoses(encounter_id,description,diagnosis_type,recorded_by) values(target_encounter,trim(new_diagnosis),'working',auth.uid());end if;insert into public.audit_events(organization_id,facility_id,actor_id,event_type,object_type,object_id,reason,details) values(org,fac,auth.uid(),'consultation.amended','encounter',target_encounter,trim(amendment_reason),jsonb_build_object('version',next_version));end$$;
grant execute on function public.amend_consultation(uuid,text,text,text,text) to authenticated;
commit;
